const source=(date,id)=>`https://trilingual.jp/bigginer/${date}-${id}/`;
const video=id=>`https://www.youtube.com/watch?v=${id}`;
const q=(id,prompt,options,answer,explanation)=>({id,prompt,options,answer,explanation});
const e=(ko,ja,zh)=>({ko,ja,zh});
const t=(title,text)=>({title,text});
const make=(id,name,url,vid,concept,teaching,examples,quiz,summary)=>({id:String(id).padStart(2,'0'),name,sourceUrl:url,videoUrl:video(vid),concept,teaching,examples,quiz,summary,duration:id===1?'40–60 分钟，可分 3 天':'20–35 分钟，可拆段',action:'打开本课视频或官方图文，按自己的速度学习并跟读；阅读中文整理，遮住译文复述例句；完成本课六题并查看解释，写一句总结',check:'完成三个学习步骤，六题测验达到 80%（至少答对五题）；发音另跟原声练习，不由文字题评分。',prompt:'我在跟随トリリンガルのトミ学韩语，日语 N2、韩语初学。请根据我贴出的本课中文整理，用中文解释并加日语对照，一次问我一道题，等我回答后再纠错。不要用日语假名代替韩语发音，也不要从文字答案判断真实发音。'});
const lessons=[
make(1,'从零准备：字母、拼读与学习方法',source('20190814','2937'),'J6r99fSUzos','官方第 1 课是学习说明。先完成字母准备，再进入第 2 课会话；这一课可以分几天完成。',[
 t('第 1 小段：先认音节方块','한글（ハングル，韩文）用字母拼成音节。开头的 ㅇ 不发音，作用是占位：ㅇ＋ㅏ＝아；ㅇ＋ㅗ＝오。竖形元音放右边，横形元音放下面。先听基本字母视频，再照着写。'),
 t('第 2 小段：基本元音与辅音','基本元音为 ㅏ ㅑ ㅓ ㅕ ㅗ ㅛ ㅜ ㅠ ㅡ ㅣ。ㅓ/ㅗ、ㅡ/ㅜ 要跟韩语原声区分；不要当成相同的日语音。基本辅音包括 ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅅ ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ。ㄱ/ㅋ/ㄲ 分别属于平音、送气音、紧音，字母视频有跟读示范。'),
 t('第 3 小段：复合元音和收音','复合元音（合成母音）如 ㅘ＝ㅗ＋ㅏ。收音（パッチム）是音节末尾的辅音：한＝ㅎ＋ㅏ＋ㄴ。开头的 ㅇ 占位，末尾的 ㅇ 发鼻音 /ŋ/，功能不同。本课先认识结构，收音音变以后反复复习。'),
 t('准备好输入','学习说明里还有电脑、手机韩语输入的教程。中文整理帮助理解；实际口形与发音跟原视频。今天不必一次记住所有字母，更不需要先背一整本单词表。')
],[e('아 / 오','縦の母音 / 横の母音','比较右侧元音和下方元音'),e('한','ㅎ＋ㅏ＋ㄴ','末尾 ㄴ 是收音'),e('강','末尾のㅇは鼻音','末尾 ㅇ 与开头 ㅇ 作用不同')],[
 q('a','아 开头的 ㅇ 在这里有什么作用？',['占位，不发音','一定读 ng','表示疑问','表示复数'],0,'元音开头的音节也需要辅音位置，因此写 ㅇ 占位；末尾的 ㅇ 才发 /ŋ/。'),
 q('b','ㅇ＋ㅗ 拼成哪个音节？',['아','오','우','어'],1,'ㅗ 是横形元音，放在 ㅇ 的下方，拼成 오。不要和 ㅜ（우）混淆。'),
 q('c','한 的收音是哪个字母？',['ㅎ','ㅏ','ㄴ','没有收音'],2,'한 可拆为 ㅎ＋ㅏ＋ㄴ，最下面的 ㄴ 就是收音（パッチム）。'),
 q('d','ㅘ 由哪两个元音组合？',['ㅗ＋ㅏ','ㅜ＋ㅓ','ㅡ＋ㅣ','ㅏ＋ㅣ'],0,'ㅘ＝ㅗ＋ㅏ。先认字形组合，再跟视频听完整音，不用假名硬套。'),
 q('e','哪组依次是平音、送气音、紧音？',['ㄱ / ㅋ / ㄲ','ㄴ / ㄹ / ㅁ','ㅋ / ㄲ / ㄱ','ㅏ / ㅗ / ㅜ'],0,'ㄱ/ㅋ/ㄲ 是对应的一组。中文“送气音”在日语教材常叫激音，紧音常叫濃音；真实听辨仍要跟原声。'),
 q('f','还不熟悉字母时，下一步最合适的是？',['直接背第 10 课句型','反复用片假名标全部韩语','回到字母视频，分段听、看、写','把日语元音和韩语元音当成完全一样'],2,'你有日语基础，但韩文字母和声音需要单独建立。先能拆开、认读，才容易跟上会话课。')
],['韩文是字母拼成的音节方块，和日语假名结构不同。','区分开头占位的 ㅇ 与末尾发音的 ㅇ。','会拆字、愿意跟原声再听一遍，就完成了今天的重要一步。']),
make(2,'自我介绍：主题助词与“是”',source('20190819','2994'),'OIV-ZXIWb8I','今天理解 저는 학생입니다：主题＋身份＋礼貌判断。',[
 t('은/는 对照日语「は」','은/는 用来提示话题，可先用日语「は」帮助理解，但两种语言的用法不是完全相同。前面的词有收音用 은，没有收音用 는：학생은、저는。'),
 t('입니다 / 입니까?','名词后接 입니다 表示礼貌的“是……”（です）；提问用 입니까?（ですか）。它们直接接在名词后，不加空格：학생입니다。저 是礼貌的“我”，日语可对照 わたし。'),
 t('今天的输出','把“我”“学生”替换进句型，先读 저는 학생입니다，再尝试提问。回答前遮住中文，检查有没有按收音选对 은/는。')
],[e('저는 학생입니다.','わたしは学生です。','我是学生。'),e('학생입니까?','学生ですか。','是学生吗？'),e('이름은 무엇입니까?','名前は何ですか。','名字是什么？')],[
 q('a','저 后的主题助词选哪个？',['은','는','을','가'],1,'저 没有收音，所以用 는，组成 저는。'),
 q('b','학생 后的主题助词选哪个？',['는','를','은','와'],2,'학생 末尾有收音 ㅇ，因此用 은。日语「学生は」可以帮助理解话题功能。'),
 q('c','“我是学生”选哪句？',['저는 학생입니다.','저는 학생입니까?','저는 학생 아닙니다.','저는 학생을.'],0,'입니다 是肯定判断句尾，对照 です；입니까? 则是在提问。'),
 q('d','학생입니까? 的意思是什么？',['不是学生','是学生吗？','学生和老师','学生在学习'],1,'名词＋입니까? 是正式礼貌的疑问形式，相当于“是……吗”。'),
 q('e','哪种空格正确？',['저 는 학생 입니다.','저는 학생입니다.','저는학생입니다.','저는 학생입 니다.'],1,'助词 붙在前面的词后，입니다 接在名词后；저는 与 학생입니다 之间分开写。'),
 q('f','은/는 可以先对照日语哪个助词理解？',['を','に','は','から'],2,'本课用「は」理解提示话题的作用。这个对照是学习桥梁，并不代表所有语境都能机械替换。')
],['有收音用 은，无收音用 는。','名词＋입니다 表示“是”，名词＋입니까? 表示“是吗”。','今天自己说一句身份介绍。']),
make(3,'这、那与否定：이/가、아닙니다',source('20190826','3163'),'eq6OZ7W8MOM','从“是”走向“不是”，并能问“这是什么”。',[
 t('이/가 对照「が」','名词有收音接 이，没有收音接 가，如 학생이、의사가。不要与主题助词 은/는 的规则混在一起。'),
 t('否定不是直接加 안','名词否定用 名词＋이/가 아닙니다（ではありません）。例如 학생이 아닙니다；疑问句尾可用 아닙니까?。前一课的 입니다 与这里的 아닙니다 不要同时使用。'),
 t('指示词对照','이것＝これ，그것＝それ，저것＝あれ，무엇＝何。이것은 무엇입니까? 表示“这是什么？” 日语「こ・そ・あ」可以帮助先理解指示关系。')
],[e('이것은 무엇입니까?','これは何ですか。','这是什么？'),e('저는 학생이 아닙니다.','わたしは学生ではありません。','我不是学生。'),e('그것은 책입니다.','それは本です。','那是书。')],[
 q('a','학생 뒤에 “不是学生”应怎样接？',['학생가 아닙니다','학생이 아닙니다','학생는 아닙니다','학생입니다 아닙니다'],1,'학생 有收音，否定判断前用 이：학생이 아닙니다。'),
 q('b','의사（医生）后选哪个？',['이 아닙니다','가 아닙니다','은 아닙니다','입니다 아닙니다'],1,'의사 没有收音，用 가 아닙니다。'),
 q('c','이것 对照哪个日语词？',['それ','あれ','これ','どこ'],2,'이것＝これ（这个）；그것＝それ，저것＝あれ。'),
 q('d','무엇 表示什么？',['谁','哪里','什么','几点'],2,'무엇＝何（什么）。本课用它问物品是什么。'),
 q('e','“我不是学生”选哪句？',['저는 학생이 아닙니다.','저는 학생입니다.','저는 학생입니까?','저는 학생가 아닙니다.'],0,'저는 是话题，학생이 아닙니다 是否定身份。两种助词可以在同一句中承担不同作用。'),
 q('f','이/가 可以先对照日语什么？',['は','が','を','と'],1,'이/가 在本课用日语「が」作为理解主格助词的桥梁。不要把它当作 은/는 的替换写法。')
],['이것/그것/저것 对照 これ/それ/あれ。','名词否定：有收音用 이，无收音用 가，再接 아닙니다。','能提问“这是什么”，再给出肯定或否定回答。']),
make(4,'正式礼貌语尾：-ㅂ니다/-습니다、-고',source('20190902','3183'),'CsOnKIOVIoM','把动词、形容词变成正式礼貌表达，再连接两个信息。',[
 t('先找词干','词典形式去掉 다 得到词干：가다→가，먹다→먹。词干无收音接 -ㅂ니다，有收音接 -습니다；所以 가다→갑니다，먹다→먹습니다。'),
 t('正式疑问','相应疑问语尾为 -ㅂ니까?/-습니까?：갑니까?、먹습니까?。니다 与 니까 不要混用；名词的 입니다 是前面学过的另一个结构。'),
 t('-고 连接信息','词干＋고 可先对照日语「〜て／〜で、そして」理解连接：크고 작다 中的连接形是 크고。完整例句 방이 크고 깨끗합니다 表示房间大而干净。它不必然表示原因。另记 ㄹ 词干在 -ㅂ니다 前脱去 ㄹ：살다→삽니다。')
],[e('학교에 갑니다.','学校へ行きます。','去学校。'),e('먹습니다.','食べます。','吃。'),e('방이 크고 깨끗합니다.','部屋が広くて、きれいです。','房间大而干净。')],[
 q('a','가다 的词干是什么？',['가다','가','갑','다'],1,'去掉词典形末尾 다，剩下 가。'),
 q('b','가다 的正式礼貌形式？',['가습니다','갑니다','가입니다','가고니다'],1,'가 词干无收音，接 -ㅂ니다，组成 갑니다。'),
 q('c','먹다 的正式礼貌形式？',['먹ㅂ니다','먹습니다','머습니다','먹입니다'],1,'먹 有收音 ㄱ，接 -습니다。'),
 q('d','“吃吗？”的正式礼貌表达？',['먹습니다.','먹습니까?','먹고.','먹입니다?'],1,'陈述为 -습니다，提问为 -습니까?。'),
 q('e','크다 用 -고 连接时变为？',['크다고','크고','큽고','커고'],1,'从词干 크 直接接 고：크고。'),
 q('f','-고 在本课主要做什么？',['连接两个动作或性质','一定表示过去','专门表示否定','把所有词变成名词'],0,'本课的 -고 用来连接信息，可先对照日语的中止连接形式理解，不能一律解释为“因为”。')
],['词典形去 다，先找词干。','无收音 -ㅂ니다，有收音 -습니다。','词干＋고 可以连接两个信息。']),
make(5,'动词与形容词否定：안、-지 않습니다',source('20190909','3358'),'aYutokhePgs','会用两种方法说“不去、不吃、不忙”，并区分名词否定。',[
 t('短否定 안','안 放在动词、形容词前并分写：안 갑니다（行きません），안 바쁩니다（忙しくありません）。不等同于表示能力做不到的 못。'),
 t('长否定 -지 않습니다','词干＋지 않습니다：먹다→먹지 않습니다。词干与 지 连写，지 与 않습니다 分写。可先对照日语「〜ない／〜ません」。'),
 t('하다 动词与名词否定','常见名词＋하다 动词可拆开否定：공부하다→공부 안 합니다。今天先记这个常见例子，不把所有 하다 词机械拆开。名词身份的“不是”仍用 이/가 아닙니다。'),
 t('顺便记星期','月火水木金土日可以借日语记：월요일、화요일、수요일、목요일、금요일、토요일、일요일。요일 相当于日语「曜日」。')
],[e('안 갑니다.','行きません。','不去。'),e('먹지 않습니다.','食べません。','不吃。'),e('공부 안 합니다.','勉強しません。','不学习。')],[
 q('a','가다 的短否定是哪一个？',['안 갑니다','갑니다 안','가 안니다','안입니다'],0,'안 放在动词前并分开写：안 갑니다。'),
 q('b','먹다 的长否定？',['먹다지 않습니다','먹지 않습니다','먹 안지 않습니다','먹는 않습니다'],1,'取词干 먹，再接 지 않습니다。'),
 q('c','공부하다 常见的短否定？',['공부 안 합니다','공부합니다 안','공부는 없습니다','안 공부입니다'],0,'名词＋하다 的常见组合可写成 공부 안 합니다。'),
 q('d','“不是学生”应优先用哪种？',['안 학생입니다','학생이 아닙니다','학생지 않습니다','학생 안 합니다'],1,'학생 是名词，身份否定用 이/가 아닙니다，不能照搬动词的否定方式。'),
 q('e','哪种分写正确？',['먹 지않습니다','먹지 않습니다','먹지않 습니다','먹 지 않습니다'],1,'먹지 连写，않습니다 作为后面的辅助用言分开写。'),
 q('f','借日语「水曜日」记韩语，星期三是哪一个？',['월요일','수요일','금요일','일요일'],1,'水曜日＝수요일。韩语的星期排列也可以借月火水木金土日理解，实际读音需跟原声。')
],['短否定：안＋用言。','长否定：词干＋지 않습니다。','身份否定仍用 이/가 아닙니다。']),
make(6,'日常礼貌的“是”：예요/이에요 与分写',source('20190916','3497'),'ZJYKZkY2CJw','把正式的 입니다 换成生活里常用的礼貌表达。',[
 t('按名词末尾选语尾','无收音名词＋예요，有收音名词＋이에요：의사예요、학생이에요。都可对照日语「です」，口语中常见。语气日常仍有礼貌。'),
 t('问句看语调','학생이에요. 可以陈述；학생이에요? 可以提问，书写常用问号区分，听力中要听语调。不要用中文疑问句规则去拼一个额外语尾。'),
 t('分写（分かち書き）','助词接在前一个词后，名词与 예요/이에요 连写：저는 학생이에요。注意常用否定形是 아니에요，不写成 아니예요。')
],[e('저는 학생이에요.','わたしは学生です。','我是学生。'),e('의사예요?','医者ですか。','是医生吗？'),e('아니에요.','違います／そうではありません。','不是。')],[
 q('a','학생 后面接哪个？',['예요','이에요','이예요','에요'],1,'학생 有收音 ㅇ，所以用 이에요。'),
 q('b','의사 后面接哪个？',['이에요','예요','이예요','입니다요'],1,'의사 无收音，用 예요。'),
 q('c','哪种常见否定拼写正确？',['아니예요','아니에요','안이에요','아닙예요'],1,'아니에요 是正确的常见否定形式，要单独记住这个拼写。'),
 q('d','“我是学生”哪句分写正确？',['저는 학생이에요.','저 는 학생 이에요.','저는학생 이에요.','저는 학생 이 에요.'],0,'저＋는、학생＋이에요 内部连写，两个语节之间分开。'),
 q('e','学生身份的正式体与日常礼貌体对应正确的是？',['학생입니다 ↔ 학생이에요','학생입니다 ↔ 학생예요','학생입니까 ↔ 학생고','학생은 ↔ 학생예요'],0,'同一个有收音名词 학생，正式判断为 입니다，日常礼貌判断为 이에요。'),
 q('f','학생이에요? 可以表达？',['是学生吗？','不是学生','正在学习','学生和老师'],0,'예요/이에요 也能用在疑问句里，通过语调和问号表达提问。')
],['有收音 이에요，无收音 예요。','助词、判断语尾都与前面的词连写。','日常礼貌语体不是随意省略礼貌。']),
make(7,'해요 体：日常动词变形的入口',source('20190923','3580'),'ncI3Tp5glnQ','官方这一课集中讲 해요 体与不规则变形。先掌握高频主干，再按原视频复习例外。',[
 t('主干规则：아/어/해요','先去 다 看词干。词干末尾元音通常为 ㅏ/ㅗ 时接 아요，其他通常接 어요；하다→해요。가다→가요，먹다→먹어요。这里的“通常”提醒你还会遇到缩约和不规则。'),
 t('常见缩约','오다→와요，보다→봐요，마시다→마셔요。不要逐字硬拼成 오아요 或 보아요 来背日常形式；先听熟、看熟常见缩约。'),
 t('不规则先认三组','듣다→들어요（ㄷ不规则）、춥다→추워요（ㅂ不规则）、모르다→몰라요（르不规则）。这是代表词，不是所有相同结尾都这样变；닫다→닫아요、입다→입어요 是规则词。其他代表词先认形：짓다→지어요（ㅅ）、빨갛다→빨개요（ㅎ）、쓰다→써요（ㅡ）。좋다→좋아요 是规则变化，不是所有 ㅎ 都脱落。官方视频可分多天回看。')
],[e('학교에 가요.','学校に行きます。','去学校。'),e('한국어를 공부해요.','韓国語を勉強します。','学习韩语。'),e('음악을 들어요.','音楽を聞きます。','听音乐。'),e('추워요.','寒いです。','冷。')],[
 q('a','먹다 的 해요 体是什么？',['먹아요','먹어요','먹해요','먹예요'],1,'먹 的元音不是 ㅏ/ㅗ，按规则接 어요。'),
 q('b','하다 的常用礼貌形式？',['하아요','해요','하어요','하예요'],1,'하다→해요，要作为高频变化记住。'),
 q('c','오다 的常用缩约形式？',['오아요','와요','워요','오해요'],1,'오＋아요 常缩约为 와요，表示“来”。'),
 q('d','듣다（听）的 해요 体？',['듣어요','들어요','들아요','드요'],1,'듣다 是 ㄷ不规则代表词，接元音开头的 어요 时 ㄷ→ㄹ，成为 들어요。'),
 q('e','춥다（冷）的 해요 体？',['춥어요','추워요','추와요','춥아요'],1,'춥다 属于 ㅂ不规则，常用形为 추워요。不是所有 ㅂ结尾都这样变化。'),
 q('f','모르다（不知道）的 해요 体？',['모러요','모르어요','몰라요','몰러요'],2,'모르다 的常用变形为 몰라요。先把它和词义一组记，再回视频理解 르不规则。')
],['日常动作先用 아요/어요/해요。','会说 가요、먹어요、해요，再逐步扩充缩约与不规则词。','这课内容较多，可以拆成“规则”和“不规则”两天。']),
make(8,'宾语、感叹与汉字数词：을/를、네요',source('20190930','3668'),'jWvm9K0k2dY','说清“做什么”，表达刚发现的感受，并开始读汉字数词。',[
 t('을/를 对照「を」','宾语有收音接 을，无收音接 를：밥을 먹어요、커피를 마셔요。助词连在名词后。日语「友達に会う」对应 친구를 만나요，「バスに乗る」对应 버스를 타요，不能逐词替换日语助词。'),
 t('-네요：新发现的感受','动词或形容词词干＋네요，常表示当下注意到的事实或感叹：맛있네요（真好吃啊）。可按语境对照日语「〜ですね」，不要把每个 ね 都机械翻成 네요。'),
 t('汉字数词（漢数詞）','1–10：일 이 삼 사 오 육 칠 팔 구 십。这里“四”是 사，对照日语汉字音读 し，但声音并不相同。11＝십일，20＝이십，24＝이십사。电话号码、日期、金额等场景常见这套数词。月份里特别记 유월（6月）、시월（10月），不是直接把 육/십 加上 월。')
],[e('밥을 먹어요.','ご飯を食べます。','吃饭。'),e('커피를 마셔요.','コーヒーを飲みます。','喝咖啡。'),e('맛있네요.','おいしいですね。','真好吃啊。'),e('이십사','二十四（にじゅうよん）','汉字数词 24')],[
 q('a','밥 后的宾语助词？',['를','을','는','가'],1,'밥 有收音 ㅂ，所以接 을。'),
 q('b','커피 后的宾语助词？',['을','이','를','은'],2,'커피 无收音，因此接 를。'),
 q('c','-네요 在本课常表达？',['当下注意到的感受或感叹','一定表示昨天','专门表示命令','数字单位'],0,'맛있네요 带有发现或感叹的语气，可按情境对照“おいしいですね”。'),
 q('d','汉字数词“四”是哪一个？',['넷','사','셋','삼'],1,'사 是汉字数词 4；넷 是下一课的固有数词 4。不要混用两套体系。'),
 q('e','汉字数词 24 是？',['이십사','십이사','이사십','스물넷'],0,'二十＝이십，再加四 사，组成 이십사。스물넷 是固有数词 24。'),
 q('f','을/를 先对照日语哪个助词？',['が','で','を','まで'],2,'本课把 을/를 与「を」对照理解宾语功能，再按收音选形。')
],['宾语有收音 을，无收音 를。','-네요 常表达刚注意到的感受。','今天用汉字数词读 4、11、24。']),
make(9,'“和”与固有数词：와/과',source('20191007','3739'),'Zmg4GVTecE0','把两个名词连接起来，并认识另一套用于计数的数词。',[
 t('와/과 对照「と」','连接名词时，无收音接 와，有收音接 과：사과와 바나나、책과 공책。注意这组的形态顺序与 은/는、을/를 不一样。'),
 t('固有数词（固有数詞）','1–10：하나 둘 셋 넷 다섯 여섯 일곱 여덟 아홉 열。20＝스물，24＝스물넷。它不是把前课的 일 이 삼 再念一遍，而是另一套词。'),
 t('数词接量词会变形','하나/둘/셋/넷/스물 放在常见量词前时变成 한/두/세/네/스무：사과 네 개（苹果四个）。注意“四”的裸数词是 넷，四个是 네 개；日语可对照「四／四つ」理解用途差别，但两种语言体系不完全一致。'),
 t('几点：小时与分钟分开选','小时常用固有数词＋시，分钟用汉字数词＋분。四点十分＝네 시 십 분，对照日语「よじじゅっぷん」。问“几点？”用 몇 시예요?，不要把四点写成 사 시 或 넷 시。')
],[e('책과 공책','本とノート','书和笔记本'),e('사과와 바나나','りんごとバナナ','苹果和香蕉'),e('사과 네 개','りんご四つ','四个苹果'),e('스물넷','二十四','固有数词 24')],[
 q('a','책 后接哪个“和”？',['와','과','를','는'],1,'책 有收音 ㄱ，用 과。'),
 q('b','사과 后接哪个“和”？',['과','이','와','을'],2,'사과 没有收音，用 와。'),
 q('c','单独说固有数词“四”是什么？',['사','넷','네 개','십'],1,'固有数词 4 是 넷；사 是汉字数词。'),
 q('d','“四个苹果”的“四个”怎么写？',['넷 개','사 개','네 개','네개'],2,'넷 在量词 개 前变为 네，数词与量词分写为 네 개。'),
 q('e','“两个”怎样表达？',['둘 개','두 개','이 개','두개'],1,'둘 放在 개 前常变为 두，因此是 두 개。'),
 q('f','“四点十分”（よじじゅっぷん）是哪一个？',['사 시 십 분','넷 시 열 분','네 시 십 분','네 시 열 분'],2,'小时用固有数词，넷 在 시 前变 네；分钟用汉字数词 십，所以是 네 시 십 분。')
],['有收音 과，无收音 와，表示名词之间的“和”。','固有数词 1–4 是 하나 둘 셋 넷。','接量词常变为 한 두 세 네。']),
make(10,'正在做什么：-고 있어요、(이)랑',source('20191014','3751'),'7raBJfl2Ybo','把学过的动作放进“正在……”句型，再说“和谁一起”。',[
 t('动作进行中：-고 있어요','动词词干＋고 있어요 表示动作正在进行：공부하고 있어요、먹고 있어요。可用日语「〜ている」理解本课用法，但两种表达的全部用法并不一一对应。'),
 t('和谁：-(이)랑','有收音名词＋이랑，无收音名词＋랑：동생이랑、친구랑。日常口语中常见，可与前课较书面的 와/과 对照；不要把 랑 和 이랑 叠加。'),
 t('把信息拼起来','친구랑 한국어를 공부하고 있어요＝正在和朋友学韩语。按“和谁＋宾语＋正在做”检查句子。不是所有状态形容词都能为了表达“现在”而直接加 고 있어요。')
],[e('지금 공부하고 있어요.','今、勉強しています。','现在正在学习。'),e('친구랑 밥을 먹고 있어요.','友達とご飯を食べています。','正在和朋友吃饭。'),e('동생이랑 이야기하고 있어요.','弟／妹と話しています。','正在和弟弟或妹妹聊天。')],[
 q('a','“正在学习”的常见礼貌表达？',['공부하고 있어요','공부예요','공부고 해요','공부합니다고'],0,'공부하다 去 다 得 공부하，再接 고 있어요。'),
 q('b','친구 后接哪种“和”？',['이랑','랑','과','을'],1,'친구 无收音，本课用 랑：친구랑。와 也可用于别的语体，但选项中没有它。'),
 q('c','동생 后接哪种“和”？',['랑','이랑','와','는'],1,'동생 有收音 ㅇ，因此用 이랑。'),
 q('d','“正在吃饭”是哪一个？',['밥을 먹고 있어요','밥을 먹지 않아요','밥이 아닙니다','밥과 공책'],0,'먹다 的词干 먹 接 고 있어요，宾语 밥 接 을。'),
 q('e','친구랑 한국어를 공부하고 있어요 的意思？',['朋友不会韩语','正在和朋友学习韩语','朋友是韩国人','我明天去学校'],1,'친구랑＝和朋友，한국어를＝韩语（宾语），공부하고 있어요＝正在学习。'),
 q('f','-고 있어요 在本课可先对照日语什么？',['〜ている（动作进行中）','〜ではない','〜たい','〜から来た'],0,'本课先学动作进行中的 -고 있어요，对照日语进行用法理解，暂不推广到所有状态表达。')
],['动词词干＋고 있어요 表示本课的动作进行中。','有收音 이랑，无收音 랑，口语中表示“和”。','自己写一句“现在正在和谁做什么”，完成十课阶段小结。'])
];
